// The Mironium logo (the silhouette mark + the "Mironium" wordmark in Nunito 800 with the
// gold italic DM Serif Display "u"), as on the landing page and public/brand/mironium-logo.svg.
// Everything is in outlines (mironiumLogoPaths.js, generated by scripts/build-brand-logo.py), so
// it renders the same in the app, in print documents and anywhere else — no font to load.
// One source for every place that draws it inline: the account screens (MironiumLogo.jsx),
// the propis2 covers and the symmetry-draw print footer.
import {
  LOGO_VIEWBOX,
  LOGO_TRANSLATE,
  LOGO_MARK_PATH,
  LOGO_WORD_PATH,
  LOGO_U_PATH,
} from "./mironiumLogoPaths.js";

export const LOGO_INK = "#1C3634";
export const LOGO_GOLD = "#C18B22";

export { LOGO_VIEWBOX, LOGO_TRANSLATE, LOGO_MARK_PATH, LOGO_WORD_PATH, LOGO_U_PATH };

export function mironiumLogoSvg({ className = "", ink = LOGO_INK, gold = LOGO_GOLD } = {}) {
  const cls = className ? ` class="${className}"` : "";
  return `<svg${cls} xmlns="http://www.w3.org/2000/svg" viewBox="${LOGO_VIEWBOX}" role="img" aria-label="Mironium"><title>Mironium</title>`
    + `<g transform="${LOGO_TRANSLATE}">`
    + `<path fill="${ink}" d="${LOGO_MARK_PATH}"/>`
    + `<path fill="${ink}" d="${LOGO_WORD_PATH}"/>`
    + `<path fill="${gold}" d="${LOGO_U_PATH}"/>`
    + `</g></svg>`;
}
